 private async Task<bool>Delete(string p,string?tipo,long id,int u,CancellationToken ct){await using var cn=connections.Create();await cn.OpenAsync(ct);await using var c=P(cn,p);if(tipo is not null)c.Parameters.Add("@Tipo",SqlDbType.NVarChar,20).Value=tipo;c.Parameters.Add("@Id",p.EndsWith("recurso")?SqlDbType.Int:SqlDbType.BigInt).Value=id;c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=u;return Convert.ToInt32(await c.ExecuteScalarAsync(ct))>0;}private static async Task<IReadOnlyList<CatalogoDto>>Next(SqlDataReader r,CancellationToken ct)=>await r.NextResultAsync(ct)?await Cats(r,ct):[];private static async Task<IReadOnlyList<CatalogoDto>>Cats(SqlDataReader r,CancellationToken ct){var x=new List<CatalogoDto>();while(await r.ReadAsync(ct))x.Add(new(r.Int32("Id"),r.Text("Nombre")));return x;}private static void Scope(SqlCommand c,AlcanceTransporte a){c.Parameters.Add("@UsuarioId",SqlDbType.Int).Value=a.UsuarioId;c.Parameters.Add("@EsAdministrador",SqlDbType.Bit).Value=a.EsAdministrador;}private static SqlCommand P(SqlConnection c,string n)=>new(n,c){CommandType=CommandType.StoredProcedure};private static object Db(object?x)=>x??DBNull.Value;private static string?T(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();private static decimal D(SqlDataReader r,string n)=>r.GetDecimal(r.GetOrdinal(n));private static int?NI(SqlDataReader r,string n){var i=r.GetOrdinal(n);return r.IsDBNull(i)?null:r.GetInt32(i);}private static void Dec(SqlCommand c,string n,decimal v,byte scale){var p=c.Parameters.Add(n,SqlDbType.Decimal);p.Precision=18;p.Scale=scale;p.Value=v;}
